using System.Drawing;using System.Windows.Forms;
namespace Synkoz { public sealed class FramePreviewR11:PictureBox { protected override void OnPaint(PaintEventArgs e){e.Graphics.Clear(Color.Black);if(Image!=null){float scale=System.Math.Min(ClientSize.Width/(float)Image.Width,ClientSize.Height/(float)Image.Height);var area=new RectangleF((Width-Image.Width*scale)/2,(Height-Image.Height*scale)/2,Image.Width*scale,Image.Height*scale);var save=e.Graphics.Save();e.Graphics.SetClip(area);using(var a=new SolidBrush(Color.FromArgb(70,70,70)))using(var b=new SolidBrush(Color.FromArgb(110,110,110)))for(int y=(int)area.Top;y<area.Bottom;y+=10)for(int x=(int)area.Left;x<area.Right;x+=10)e.Graphics.FillRectangle(((x-(int)area.Left)/10+(y-(int)area.Top)/10)%2==0?a:b,x,y,10,10);e.Graphics.Restore(save);base.OnPaint(e);e.Graphics.DrawRectangle(Pens.Silver,area.X,area.Y,System.Math.Max(0,area.Width-1),System.Math.Max(0,area.Height-1));}}}}
